if($step==='review'&&$_SERVER['REQUEST_METHOD']==='POST'){
 $selected=[];for($d=1;$d<=3;$d++){$selected[$d]=array_values(array_unique(array_filter(array_map('intval',$_POST['selected'][$d]??[]))));if(count($selected[$d])>3)$selected[$d]=array_slice($selected[$d],0,3);}
 $_SESSION['ready_trip_selection'][$key]=$selected;
}
$selected=$_SESSION['ready_trip_selection'][$key]??[1=>[],2=>[],3=>[]];
if($step==='final'&&$_SERVER['REQUEST_METHOD']==='POST'){$selected=[];for($d=1;$d<=3;$d++)$selected[$d]=array_values(array_unique(array_filter(array_map('intval',$_POST['selected'][$d]??[]))));$_SESSION['ready_trip_selection'][$key]=$selected;}
$placeMap=[];foreach($places as $p)$placeMap[(int)$p['Place_ID']]=$p;
trip_header($trip['title'],'itinerary'); ?>
