<?php for($day=1;$day<=3;$day++):?><div class="trip-day"><div class="trip-day-heading"><h2>Day <?=$day?></h2><span class="about-label">CHOOSE UP TO 3 PLACES</span></div>
<div class="trip-place-list"><?php foreach($places as $p):?><label class="trip-place"><input type="checkbox" class="ready-place-check" name="selected[<?=$day?>][]" value="<?=(int)$p['Place_ID']?>" <?=in_array((int)$p['Place_ID'],$selected[$day]??[],true)?'checked':''?>><span><?php if($p['Image']):?><img src="<?=trip_e($p['Image'])?>" alt="<?=trip_e($p['Name'])?>"><?php else:?><span style="display:grid;place-items:center;width:104px;height:92px;background:#edf2ee;border-radius:11px;">🌴</span><?php endif;?></span><span><h3><?=trip_e($p['Name'])?></h3><p><?=trip_e(ucfirst($p['Place_Type']))?> · <?=trip_e($p['Location'])?></p><p><?=trip_e($p['Short_Description'])?></p></span></label><?php endforeach;?></div>
</div><?php endfor;?>
<div class="trip-actions"><a class="trip-action secondary" href="ready-made-trips.php">← Back</a><button class="trip-action" type="submit">Next: Review My Trip <span>→</span></button></div></form></div></section>
<script>document.querySelectorAll('.trip-day').forEach(day=>{const checks=day.querySelectorAll('.ready-place-check');checks.forEach(c=>c.addEventListener('change',()=>{const chosen=[...checks].filter(x=>x.checked);if(chosen.length>3){c.checked=false;alert('Please choose up to three places for each day.');}}));});</script>
<?php elseif($step==='review'):?>
<section class="about-content-section"><div class="about-intro-card"><h2>Review Your Choices</h2><p>Here is how your selected places will be arranged.</p>
<?php $hasSelection=false;for($d=1;$d<=3;$d++):?><div class="trip-day"><div class="trip-day-heading"><h2>Day <?=$d?></h2><span class="about-label"><?=count($selected[$d]??[])?> SELECTED</span></div><div class="trip-place-list"><?php foreach($selected[$d]??[] as $pid):if(!isset($placeMap[$pid]))continue;$hasSelection=true;$p=$placeMap[$pid];?><article class="trip-place"><?php if($p['Image']):?><img src="<?=trip_e($p['Image'])?>" alt="<?=trip_e($p['Name'])?>"><?php else:?><div style="width:104px;height:92px;border-radius:11px;background:#edf2ee;display:grid;place-items:center;">🌴</div><?php endif;?><div><h3><?=trip_e($p['Name'])?></h3><p><?=trip_e($p['Short_Description']?:$p['Place_Type'])?></p><p><?=trip_e($p['Location'])?></p></div></article><?php endforeach;?></div><?php if(empty($selected[$d])):?><p class="trip-empty">No places selected for this day.</p><?php endif;?></div><?php endfor;?>
